import React from 'react';
import { Button } from '@/components/ui/button';
import { Trash2 } from 'lucide-react';

const DarDeBaja = () => {
  return (
    <div className="space-y-4">
      <h3 className="text-xl font-semibold text-gray-800">Dar de Baja a Estudiante</h3>
      <p className="text-gray-600">
        En esta sección puede dar de baja a un estudiante del sistema. Esta acción es irreversible y se recomienda realizarla solo cuando sea estrictamente necesario.
      </p>

      <form className="bg-white rounded-lg shadow p-4 space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700">Buscar Estudiante</label>
          <input
            type="text"
            placeholder="Ingrese el nombre o CI del estudiante"
            className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
          />
        </div>

        <div className="flex justify-end">
          <Button className="bg-red-600 hover:bg-red-700 text-white flex items-center">
            <Trash2 className="w-4 h-4 mr-2" /> Dar de Baja
          </Button>
        </div>
      </form>
    </div>
  );
};

export default DarDeBaja;
